WITH flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '1' HOUR THEN 1 ELSE 0 END AS new_group_flag FROM device_readings), sessions_device_readings AS (SELECT id, device_code, reading_ts, status_bits, firmware, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT id, device_code, reading_ts, status_bits, CASE WHEN device_code RLIKE '^(DV-03|DV-02)$' THEN 'OTHER_ZONE' WHEN device_code RLIKE '^(DV-01|DV-04)$' THEN 'GROUP_A' ELSE 'GROUP_B' END AS device_code_zone FROM sessions_device_readings ORDER BY reading_ts NULLS FIRST;
